(function () {
  "use strict";

  class Chart {
    constructor(ctx, config) {
      this.ctx = ctx;
      this.canvas = ctx.canvas;
      this.data = config.data || { labels: [], datasets: [] };
      this.options = config.options || {};
      this.update();
    }

    update() {
      const ctx = this.ctx;
      const cssWidth = this.canvas.clientWidth || 480;
      const cssHeight = this.canvas.clientHeight || 200;
      const scale = window.devicePixelRatio || 1;
      if (this.canvas.width !== Math.floor(cssWidth * scale)) this.canvas.width = Math.floor(cssWidth * scale);
      if (this.canvas.height !== Math.floor(cssHeight * scale)) this.canvas.height = Math.floor(cssHeight * scale);
      ctx.setTransform(scale, 0, 0, scale, 0, 0);
      ctx.clearRect(0, 0, cssWidth, cssHeight);

      const pad = { left: 34, right: 12, top: 16, bottom: 24 };
      const w = Math.max(1, cssWidth - pad.left - pad.right);
      const h = Math.max(1, cssHeight - pad.top - pad.bottom);
      const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
      const values = (dataset.data || []).map((v) => Number(v) || 0);

      ctx.strokeStyle = "#2a2a3e";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i += 1) {
        const y = pad.top + (h * i) / 4;
        ctx.beginPath();
        ctx.moveTo(pad.left, y);
        ctx.lineTo(pad.left + w, y);
        ctx.stroke();
      }

      ctx.fillStyle = "#888";
      ctx.font = "10px monospace";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      for (let i = 0; i <= 4; i += 1) {
        const value = 1 - i / 4;
        ctx.fillText(value.toFixed(2), pad.left - 6, pad.top + (h * i) / 4);
      }

      if (!values.length) {
        ctx.fillStyle = "#888";
        ctx.textAlign = "center";
        ctx.fillText("waiting for results...", cssWidth / 2, cssHeight / 2);
        return;
      }

      const points = values.map((value, idx) => ({
        x: pad.left + (values.length === 1 ? w : (w * idx) / (values.length - 1)),
        y: pad.top + h - Math.max(0, Math.min(1, value)) * h,
      }));

      ctx.beginPath();
      points.forEach((p, idx) => {
        if (idx === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.strokeStyle = dataset.borderColor || "#40916c";
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.lineTo(points[points.length - 1].x, pad.top + h);
      ctx.lineTo(points[0].x, pad.top + h);
      ctx.closePath();
      ctx.fillStyle = dataset.backgroundColor || "rgba(64,145,108,0.12)";
      ctx.fill();
    }
  }

  window.Chart = Chart;
})();

